                    '敌对': 'negative', '鼎炉': 'negative', '采补': 'negative'
                },
                '任务类型': { '日常任务': 'primary', '大事件': 'warning', '世界级任务': 'negative' },
                '难度': { '简单': 'primary', '一般': 'info', '困难': 'warning', '地狱': 'negative' },
                '状态': { '未开始': 'primary', '进行中': 'warning', '已完成': 'positive' },
                '类别': { '法宝': 'info', '丹药': 'positive', '仙法': 'warning', '其他': 'primary' },
                '品阶': {
                    '法器': 'primary', '灵器': 'positive', '宝器': 'warning', '仙器': 'negative', '道器': 'info', '神器': 'info',
                    '普通丹药': 'primary', '灵丹': 'positive', '极品丹': 'warning', '仙丹': 'negative', '神丹': 'info',
                    '凡术': 'primary', '灵术': 'positive', '玄术': 'warning', '仙术': 'negative', '道术': 'info', '禁术': 'info'
                }
            }
        };

        // --- 辅助函数 ---
        const getIconForField = (field, value = '') => {
            // 特殊处理性别字段
            if (field === '性别') {
                if (value === '男') return 'fa-person';  // 男性使用人物图标
                if (value === '女') return 'fa-person-dress';  // 女性使用裙装人物图标
                if (value === '未知') return 'fa-user-secret';  // 未知性别使用神秘人物图标
            }

            return {
                '姓名': 'fa-signature', '年龄': 'fa-birthday-cake', '种族': 'fa-dragon', '职业': 'fa-briefcase', '职业/身份': 'fa-id-card',
                '境界': 'fa-level-up-alt', '灵根': 'fa-seedling', '法力总值': 'fa-bolt', '欲锁阶层': 'fa-lock', '适用境界': 'fa-level-up-alt',
                '美貌': 'fa-face-grin-stars', '身材': 'fa-person-dots-from-line', '衣着姿势': 'fa-tshirt', '性格': 'fa-brain',
                '好感度': 'fa-heart', '堕落值': 'fa-arrow-down-wide-short', '性欲值': 'fa-fire-flame-curved', '性癖': 'fa-mask',
                '性经验': 'fa-book-medical', '关系': 'fa-link', '最近性行为': 'fa-clock', '身体状态': 'fa-heart-pulse',
                '任务名称': 'fa-flag', '任务类型': 'fa-tag', '难度': 'fa-gauge-high', '奖励': 'fa-gift', '惩罚': 'fa-skull',
                '时间': 'fa-calendar', '地点': 'fa-location-dot', '状态': 'fa-spinner', '参与者': 'fa-users',
                '物品名': 'fa-box-open', '类别': 'fa-tag', '描述': 'fa-file-alt', '数量': 'fa-calculator',
                '品阶': 'fa-gem', '效果': 'fa-wand-magic-sparkles', '获取时间': 'fa-calendar-alt', '持有者': 'fa-user-tag'
            }[field] || 'fa-circle-info';
        };

        const getIconForType = type => ({
            'npc': 'fa-user',
            'task': 'fa-tasks',
            'item': 'fa-boxes-stacked'
        })[type] || 'fa-circle-info';

        const formatMultiValue = (value, field) => {
            const valueStr = (value === null || value === undefined) ? '' : String(value).trim();
            if (!valueStr || valueStr.toLowerCase() === '无' || valueStr.toLowerCase() === '未知') {
                return `<span class="value-tag">${valueStr || '无'}</span>`;
            }
            if (['好感度', '堕落值', '性欲值'].includes(field)) {
                const numericValue = Math.max(0, Math.min(100, parseInt(valueStr) || 0));
                const progressClass = {
                    '好感度': numericValue >= 80 ? 'positive' : numericValue >= 40 ? 'info' : numericValue > 0 ? 'warning' : 'negative',
                    '堕落值': numericValue >= 80 ? 'negative' : numericValue >= 40 ? 'warning' : 'positive',
                    '性欲值': numericValue >= 70 ? 'warning' : numericValue >= 40 ? 'neutral' : 'info'
                }[field];
                const displayPercent = field === '好感度' ? (numericValue + 100) / 2 : numericValue;
                return `<div class="progress-display"><span class="progress-text">${valueStr}</span><div class="progress-bar-container"><div class="progress-bar ${progressClass}" style="width: ${displayPercent}%;" title="${numericValue}%">${numericValue}%</div></div></div>`;
            }
            if (['衣着姿势', '身体状态'].includes(field)) {
                return `<div class="body-status">${valueStr.split(';').map(part => {
                    const [icon, details] = part.split(': ');
                    return `<div class="body-part"><div class="body-part-icon">${icon}</div><div class="body-part-details">${details}</div></div>`;
                }).join('')}</div>`;
            }
            if (field === '最近性行为') {
                return `<div class="tags-container">${valueStr.split(';').map(item => {
                    const [time, details] = item.split(':').map(s => s.trim());
                    return `<span class="value-tag"><span class="detail-key">${time}:</span><span class="detail-value">${details}</span></span>`;
                }).join('')}</div>`;
            }
            const getColorClass = (value, field) => {
                if (field in colorMaps.special) {
                    const fieldMap = colorMaps.special[field];
                    if (value in fieldMap) return fieldMap[value];
                }
                return 'neutral';
            };
            if (field in colorMaps.special) {
                return `<div class="tags-container">${valueStr.split(';').map(item => {
                    const colorClass = getColorClass(item.trim(), field);
                    return `<span class="value-tag ${colorClass}">${item.trim()}</span>`;
                }).join('')}</div>`;
            }
            if (valueStr.includes(';')) {
                return `<div class="tags-container">${valueStr.split(';').map(item => {
                    return `<span class="value-tag">${item.trim()}</span>`;
                }).join('')}</div>`;
            }
            return valueStr;
        };

        // --- 数据解析函数 ---
        const parseDataString = text => {
            if (!text?.trim()) return { npcs: [], tasks: [], items: [] };
            const data = { npcs: [], tasks: [], items: [] };
            const sections = {
                'NPC': { key: 'npcs', prefix: 'NPC:' },
                'TASK': { key: 'tasks', prefix: 'TASK:' },
                'ITEM': { key: 'items', prefix: 'ITEM:' }
            };

            const findLastBlock = (type, fullText) => {
                const startTag = `>>${type}_LIST_START`;
                const endTag = `>>${type}_LIST_END`;
                const regex = new RegExp(`${startTag.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&')}([\\s\\S]*?)${endTag.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&')}`, 'g');
                let lastMatch = null;
                let match;
                while ((match = regex.exec(fullText)) !== null) lastMatch = match;
                return lastMatch?.[1];
            };

            for (const [type, { key, prefix }] of Object.entries(sections)) {
                const content = findLastBlock(type, text);
                if (!content) continue;

                const lines = content.trim().split('\n').map(l => l.trim()).filter(l => l);
                    const fieldsLineIndex = lines.findIndex(l => l.startsWith('FIELDS:'));
                if (fieldsLineIndex === -1) continue;

                const fields = lines[fieldsLineIndex].substring(7).split('|').map(f => f.trim()).filter(f => f);
                const dataLines = lines.slice(fieldsLineIndex + 1).filter(l => l.startsWith(prefix));

                dataLines.forEach(line => {
                    const values = line.substring(prefix.length).split('|', fields.length).map(v => v.trim());
                        if (values.length === fields.length) {
                            const entry = {};
                            fields.forEach((field, index) => {
                            let value = values[index] || '';
                            if (!value) {
                                value = field.includes('%') || field.includes('值') || field.includes('度') || ['年龄', '数量', '法力总值'].includes(field) ? '0' :
                                    ['最近性行为', '性癖', '状态', '效果'].includes(field) ? '无' : '无';
                                }
                                entry[field] = value;
                            });
                        data[key].push(entry);
                        }
                    });
            }

            return data;
        };

        // --- 渲染函数 ---
        const renderSidebar = data => {
            elements.sidebarContent.innerHTML = '';
            elements.errorMessage.style.display = 'none';

            const categories = [
                { type: 'npc', title: '人物信息', icon: 'fa-user', data: data.npcs, nameField: '姓名', defaultExpanded: true },
                { type: 'task', title: '任务列表', icon: 'fa-tasks', data: data.tasks, nameField: '任务名称', defaultExpanded: false },
                { type: 'item', title: '物品信息', icon: 'fa-boxes-stacked', data: data.items, nameField: '物品名', defaultExpanded: false }
            ];

            const hasData = categories.some(cat => Array.isArray(cat.data) && cat.data.length > 0);

            if (!hasData) {
                elements.sidebarContent.innerHTML = '<div class="no-data-message">当前无可用数据</div>';
                clearDetails();
                return;
            }

            categories.forEach(cat => {
                if (!Array.isArray(cat.data) || !cat.data.length) return;

                    const categoryDiv = document.createElement('div');
                    categoryDiv.className = 'sidebar-category';

                    const headerDiv = document.createElement('div');
                    headerDiv.className = 'category-header';
                    headerDiv.innerHTML = `
                        <h3 class="category-title">
                            <i class="fas ${cat.icon}"></i>
                        ${cat.title} (${cat.data.length})
                        </h3>
                        <i class="fas fa-chevron-down category-toggle ${cat.defaultExpanded ? '' : 'collapsed'}"></i>
                    `;

                    const contentDiv = document.createElement('div');
                    contentDiv.className = `category-content ${cat.defaultExpanded ? '' : 'collapsed'}`;

                    const listEl = document.createElement('ul');
                    listEl.className = 'category-list';

                cat.data.forEach(item => {
                    const displayName = cat.type === 'item' && item['数量'] ? 
                        `${item[cat.nameField]}(${item['数量']})` : 
                        cat.type === 'npc' && item['性别'] ?
                        `${item[cat.nameField]}(${item['性别']})` :
                        item[cat.nameField] || `未命名 (${cat.type})`;

                        const itemId = `${cat.type}-${item[cat.nameField]}`;
                        const listItem = document.createElement('li');
                        listItem.className = 'list-item';
                        listItem.textContent = displayName;
                        listItem.title = displayName;
                        listItem.dataset.type = cat.type;
                        listItem.dataset.id = itemId;
                    listItem.addEventListener('click', () => displayDetails(cat.type, itemId));
                        listEl.appendChild(listItem);
                    });

                    contentDiv.appendChild(listEl);
                    categoryDiv.appendChild(headerDiv);
                    categoryDiv.appendChild(contentDiv);

                    headerDiv.addEventListener('click', () => {
                        const toggle = headerDiv.querySelector('.category-toggle');
                        const content = categoryDiv.querySelector('.category-content');
                        content.classList.toggle('collapsed');
                        toggle.classList.toggle('collapsed');
                    });

                elements.sidebarContent.appendChild(categoryDiv);
            });

                if (currentDataType && currentDataId) {
                const selectedElement = elements.sidebarContent.querySelector(`.list-item[data-type="${currentDataType}"][data-id="${CSS.escape(currentDataId)}"]`);
                    if (selectedElement) {
                        selectedElement.classList.add('selected');
                    if (elements.detailsView.style.display === 'none') {
                            displayDetails(currentDataType, currentDataId);
                        }
                    } else {
                        clearDetails();
                    }
                } else {
                    clearDetails();
                }
        };

        const displayDetails = (type, combinedId) => {
            const actualId = combinedId.substring(type.length + 1);
            const dataSet = {
                'npc': { data: parsedData.npcs, nameField: '姓名' },
                'task': { data: parsedData.tasks, nameField: '任务名称' },
                'item': { data: parsedData.items, nameField: '物品名' }
            }[type];

            if (!dataSet || !Array.isArray(dataSet.data)) {
                 clearDetails();
                 return;
             }

            selectedItem = dataSet.data.find(item => item[dataSet.nameField] === actualId);
             if (!selectedItem) {
                 clearDetails();
                 return;
             }

             currentDataType = type;
             currentDataId = combinedId;

            // 根据性别设置不同的图标
            if (type === 'npc' && selectedItem['性别']) {
                elements.detailIcon.className = `fas ${getIconForField('性别', selectedItem['性别'])} detail-icon`;
            } else {
                elements.detailIcon.className = `fas ${getIconForType(type)} detail-icon`;
            }

            elements.detailName.textContent = selectedItem[dataSet.nameField];

            const subtitles = {
                'npc': `${selectedItem['种族'] || '?'}, ${selectedItem['境界'] || '?'}, ${selectedItem['职业/身份'] || '未知身份'}`,
                'task': `${selectedItem['任务类型'] || '?'} | ${selectedItem['难度'] || '?'} | ${selectedItem['状态'] || '未知状态'}`,
                'item': `${selectedItem['类别'] || '未知类别'}${selectedItem['品阶'] && selectedItem['品阶'] !== '无' ? ', '+selectedItem['品阶'] : ''}`
            };
            elements.detailSubtitle.textContent = subtitles[type];

            elements.detailAttributes.innerHTML = '';
            Object.entries(selectedItem)
                .filter(([key]) => key !== dataSet.nameField && key !== '性别') // 过滤掉性别字段，不显示在属性列表中
                .forEach(([key, value]) => {
                    const itemDiv = document.createElement('div');
                    itemDiv.className = 'attribute-item';
                    itemDiv.innerHTML = `
                        <div class="attribute-key">
                            <i class="fas ${getIconForField(key, value)}"></i> ${key}
                        </div>
                        <div class="attribute-value" data-field="${key}">
                            ${formatMultiValue(value, key)}
                        </div>
                    `;
                    elements.detailAttributes.appendChild(itemDiv);
                });

            elements.placeholderMessage.style.display = 'none';
            elements.detailsView.style.display = 'flex';
            elements.errorMessage.style.display = 'none';

            document.querySelectorAll('.sidebar .list-item').forEach(el => {
                el.classList.toggle('selected', el.dataset.type === currentDataType && el.dataset.id === currentDataId);
            });
        };

        const clearDetails = () => {
            elements.placeholderMessage.style.display = 'flex';
            elements.detailsView.style.display = 'none';
            elements.errorMessage.style.display = 'none';
            resetSelectionState();
            document.querySelectorAll('.sidebar .list-item.selected').forEach(el => el.classList.remove('selected'));
        };

        const resetSelectionState = () => {
            selectedItem = null;
            currentDataType = null;
            currentDataId = null;
        };

        // --- 初始化和数据处理流程 ---
        const processRawData = () => {
            const rawText = elements.dataInjection?.textContent || elements.dataInjection?.innerText || '';

            if (!elements.dataInjection) {
                elements.sidebarContent.innerHTML = '<div class="error-message">内部错误: 缺少数据容器</div>';
                elements.errorMessage.textContent = '页面结构错误。';
                elements.errorMessage.style.display = 'block';
                clearDetails();
                return;
            }

            if (!rawText.trim()) {
                elements.sidebarContent.innerHTML = '<div class="no-data-message">未接收到有效数据。</div>';
                clearDetails();
                parsedData = { npcs: [], children: [], items: [] };
                renderSidebar(parsedData);
                return;
            }

            try {
                parsedData = parseDataString(rawText);
                renderSidebar(parsedData);

                if (currentDataType && currentDataId) {
                    const actualId = currentDataId.substring(currentDataType.length + 1);
                    const dataSet = {
                        'npc': { data: parsedData.npcs, nameField: '姓名' },
                        'task': { data: parsedData.tasks, nameField: '任务名称' },
                        'item': { data: parsedData.items, nameField: '物品名' }
                    }[currentDataType];

                    if (dataSet && Array.isArray(dataSet.data) && dataSet.data.some(item => item[dataSet.nameField] === actualId)) {
                        displayDetails(currentDataType, currentDataId);
                    } else {
                        clearDetails();
                    }
                } else if (elements.detailsView.style.display !== 'none' && !document.querySelector('.sidebar .list-item.selected')) {
                    clearDetails();
                }
            } catch (error) {
                elements.sidebarContent.innerHTML = `<div class="error-message">处理数据出错: ${error.message}</div>`;
                elements.errorMessage.textContent = `JS错误: ${error.message}. 查看控制台。`;
                elements.errorMessage.style.display = 'block';
                clearDetails();
            }
        };

        // --- 初始化 ---
        const init = () => {
            if (!elements.dataInjection) {
                document.body.innerHTML = '<div class="error-message">错误：HTML结构不完整。</div>';
                return;
            }

            processRawData();

            if (typeof MutationObserver !== 'undefined') {
                const observer = new MutationObserver(mutationsList => {
                    for (const mutation of mutationsList) {
                        if (mutation.type === 'characterData' || mutation.type === 'childList') {
                            setTimeout(processRawData, 150);
                            break;
                        }
                    }
                });

                if (elements.dataInjection) {
                    observer.observe(elements.dataInjection, { characterData: true, childList: true, subtree: true });
                }
            }
        };

        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', init);
        } else {
            init();
        }

    </script>
</body>
</html>
